{
  "title": "Al-Yamamah Professional Services Employment Application and Terms",
  "planted": [
    {
      "slot": "p1",
      "text": "To maintain a comprehensive historical talent pool for future organizational needs, all submitted application files, supporting documents, and assessment records shall be retained indefinitely by the company without scheduled deletion, ensuring historical profiles remain accessible to internal human resources personnel across all future operational cycles."
    },
    {
      "slot": "p2",
      "text": "Applicants retain the absolute right to inquire regarding the specific operational purposes and justification bases for collecting their details, to review their stored records upon formal written request, to submit amendments for any inaccurate entries, and to demand the permanent erasure of their application files in the event that the vacancy is filled or closed, subject only to ongoing legal disputes or mandatory statutory archiving obligations."
    },
    {
      "slot": "p3",
      "text": "Submission of this application constitutes the candidate's acknowledgment that their professional credentials and background information will be processed as necessary for evaluation purposes, and candidates may communicate regarding their participation status through standard administrative channels."
    }
  ],
  "neutral": [
    "This Agreement shall commence on the date of final signature by both parties and shall remain in full force and effect for an initial period of twelve months, subject to standard termination procedures.",
    "Either party may terminate this contractual relationship by providing a thirty-day written notice to the designated representative without incurring any penalty.",
    "All service fees and payment schedules shall be strictly adhered to as outlined in the separate commercial addendum provided prior to project execution.",
    "Payments shall be transferred via wire transfer to the designated corporate bank account within fifteen business days following the issuance of a valid invoice.",
    "The total aggregate liability of the company arising out of or in connection with this contract shall in no circumstances exceed the total fees paid by the client under this agreement.",
    "All proprietary methodologies, software, trademarks, and written materials developed by the company prior to or during the engagement shall remain the exclusive intellectual property of the company.",
    "Any formal notices required under this agreement shall be delivered via certified courier or electronic mail to the official addresses registered by the respective parties.",
    "This agreement shall be governed by and construed in accordance with the laws applicable in the jurisdiction of the corporate headquarters, without regard to conflict of law principles."
  ]
}
